/* @lc app=leetcode id=3362 lang=kotlin */ class Solution { fun maxRemoval(nums: IntArray, queries: Array<IntArray>): Int = queries.sortedBy { it[0] }.let { qs -> java.util.PriorityQueue<Int>(compareByDescending<Int> { it }).let { pq -> IntArray(nums.size + 2).let { exp -> IntArray(1).let { act -> IntArray(1).let { used -> nums.indices.fold(0) { qi, i -> (qi + (qi until qs.size).takeWhile { qs[it][0] <= i }.onEach { pq.add(qs[it][1]) }.count()).also { act.set(0, act[0] - exp[i]) }.also { generateSequence(1) { if (act[0] < nums[i] && used[0] >= 0) (if (pq.isNotEmpty() && pq.peek() >= i) pq.poll().also { r -> exp.set(r + 1, exp[r + 1] + 1) }.also { act.set(0, act[0] + 1) }.also { used.set(0, used[0] + 1) } else used.set(0, -1)).let { 1 } else null }.count() } }.let { if (used[0] < 0) -1 else qs.size - used[0] } } } } } } }